23f","description":"Christiaan Huygens","correct_answer":false},{"id":"01a2190a-ae7b-73cf-a1a2-aa9f90b4f88f","description":"Johannes Kepler","correct_answer":false},{"id":"01a2190a-ae7b-780f-8c53-6b63a62e56a6","description":"Galileo Galilei","correct_answer":false}]},{"id":"01a2190a-ae7b-7892-84fa-e633f783d107","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which of the following conditions can lead to blindness if left untreated?","difficulty":1,"explanation":"A cataract clouds the eye\u2019s lens; surgery can restore sight by replacing the cloudy lens with an artificial one.","alternatives":[{"id":"01a2190a-ae7b-7aa2-bdde-cbf88d4ed6a2","description":"Cataract","correct_answer":true},{"id":"01a2190a-ae7b-703a-8922-cc157d8f46b7","description":"Arthritis","correct_answer":false},{"id":"01a2190a-ae7b-78de-8f57-a8b6a0401585","description":"Mumps","correct_answer":false},{"id":"01a2190a-ae7b-7955-897c-52f14ddc1f78","description":"Jaundice","correct_answer":false}]},{"id":"01a2190a-ae7b-7b99-95cf-b3a4c2d06410","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What determines the color of our skin?","difficulty":1,"explanation":"Melanin absorbs ultraviolet radiation, helping protect skin cells from sun damage; differences in its amount and type contribute to skin color.","alternatives":[{"id":"01a2190a-ae7b-70fa-bc68-bca67d6506da","description":"Melanin","correct_answer":true},{"id":"01a2190a-ae7b-7990-a812-03ee69de41a3","description":"Collagen","correct_answer":false},{"id":"01a2190a-ae7b-751c-8920-760a3144d098","description":"Cadmium","correct_answer":false},{"id":"01a2190a-ae7b-7313-9fbc-d88fe4dd630b","description":"Calcitonin","correct_answer":false}]},{"id":"01a2190a-ae7b-76d9-b348-b67dfd68af1e","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which lizard is able to change the color of its skin?","difficulty":1,"explanation":"Chameleons often change color to signal mood or regulate body temperature, not just to blend into thei