0a-ae7d-7d49-b884-fc371699985a","description":"Dermatologist","correct_answer":true},{"id":"01a2190a-ae7d-7a65-b05a-fdc718948403","description":"Permologist","correct_answer":false},{"id":"01a2190a-ae7d-7b0b-94be-86ece6d706a0","description":"Skin Clinician","correct_answer":false},{"id":"01a2190a-ae7d-744a-bee5-8a0d024cfa03","description":"Visologist","correct_answer":false}]},{"id":"01a2190a-ae7d-70ae-8c69-f3648252b2da","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"How many kidneys do humans have?","difficulty":1,"explanation":"Humans typically have two kidneys, one on each side of the spine; many people can live with just one functioning kidney.","alternatives":[{"id":"01a2190a-ae7d-7011-ba5d-df71bcdbc51b","description":"2","correct_answer":true},{"id":"01a2190a-ae7d-739b-9baa-cc53b4c40506","description":"1","correct_answer":false},{"id":"01a2190a-ae7d-7274-9f7c-7c7556230cf1","description":"4","correct_answer":false},{"id":"01a2190a-ae7d-7f0d-b908-e99a6f0f76f1","description":"8","correct_answer":false}]},{"id":"01a2190a-ae7d-734d-83ce-10447282f811","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"How long does it take for Earth to rotate around its axis?","difficulty":1,"explanation":"A full turn relative to the Sun takes about 24 hours; relative to distant stars, Earth rotates in about 23 hours and 56 minutes.","alternatives":[{"id":"01a2190a-ae7d-7a17-b917-3c82cb57f677","description":"~24 hours","correct_answer":true},{"id":"01a2190a-ae7d-7ff5-9596-426fadf34abb","description":"~28 days","correct_answer":false},{"id":"01a2190a-ae7d-7b5d-8222-bed9ddf4484d","description":"~365 days","correct_answer":false},{"id":"01a2190a-ae7d-7651-b478-c050fa410755","description":"~1 hour","correct_answer":false}]},{"id":"01a2190a-ae7d-73b6-8c10-a18fa3e843e6","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is biology the study of?","difficulty":1,"explanation":"Biology\'s name comes from Greek roots meaning \u201clife\u201d and \u201cstudy.\u201d","alternatives":[{"id":"01a2190a-ae7d-779f-a5cb-98d0deb0bf1a","description":"Life","correct_answer":true},{"id":"01a2190a-ae7d-7908-820a-84550a37e13d","description":"Bell ringing","correct_answer":false},{"id":"01a2190a-ae7d-7e1b-93c3-12fef1097cf0","description":"Rheumatic diseases","correct_answer":false},{"id":"01a2190a-ae7d-7edf-9d9b-dd593871b9be","description":"Syphilis","correct_answer":false}]},{"id":"01a2190a-ae7d-7545-8df7-cf0639b777d5","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which scientist is said to have been inspired to develop his theory of gravity by a falling apple?","difficulty":1,"explanation":"Isaac Newton\'s law of universal gravitation describes the same force pulling an apple toward Earth and keeping planets in orbit.","alternatives":[{"id":"01a2190a-ae7d-7fd0-8d3a-e63d8ec31461","description":"Isaac Newton","correct_answer":true},{"id":"01a2190a-ae7d-7f0c-a028-49dde03c9a93","description":"Charles Darwin","correct_answer":false},{"id":"01a2190a-ae7d-74ee-b72d-df942a3b9f15","description":"Galileo Galilei","correct_answer":false},{"id":"01a2190a-ae7d-780d-b926-6a8b171dd21c","description":"Ernest Rutherford","correct_answer":false}]},{"id":"01a2190a-ae7d-74f5-a9af-ece816bd09c8","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the word for a female fox?","difficulty":1,"explanation":"A vixen is a female fox; a male fox is often called a dog, and a young fox is a cub.","alternatives":[{"id":"01a2190a-ae7d-7a79-a692-df52c61f9cd7","description":"A Vixen","correct_answer":true},{"id":"01a2190a-ae7d-71e8-8783-4b00fe911af5","description":"A Ewe","correct_answer":false},{"id":"01a2190a-ae7d-7e36-b658-40e9aa71758b","description":"A Hen","correct_answer":false},{"id":"01a2190a-ae7d-7eea-a320-4ce5315d0469","description":"A Doe","correct_answer":false}]},{"id":"01a2190a-ae7d-75fd-a714-2b25122e55cf","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Siamese and Burmese are breeds of which animal?","difficulty":1,"explanation":"Cats of the Siamese breed commonly have blue eyes and color-point coats, while Burmese cats typically have short, glossy coats.","alternatives":[{"id":"01a2190a-ae7d-7890-891c-bdf89539def0","description":"Cat","correct_answer":true},{"id":"01a2190a-ae7d-7213-b103-7a60ca1ec403","description":"Dog","correct_answer":false},{"id":"01a2190a-ae7d-75ee-a519-27b56457f158","description":"Donkey","correct_answer":false},{"id":"01a2190a-ae7d-7454-bb4d-c5b2ed44562d","description":"Pig","correct_answer":false}]},{"id":"01a2190a-ae7d-7090-a723-b4f319691560","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Who is known for his theory of evolution by natural selection?","difficulty":1,"explanation":"Charles Darwin presented his theory in On the Origin of Species, drawing on observations from his voyage aboard HMS Beagle.","alternatives":[{"id":"01a2190a-ae7d-7200-bd5e-d938e39eaeca","description":"Charles Darwin","correct_answer":true},{"id":"01a2190a-ae7d-73b4-97dc-6ce9031ebb70","description":"Albert Einstein","correct_answer":false},{"id":"01a2190a-ae7d-7942-9c55-30020d1cf886","description":"Niels Bohr","correct_answer":false},{"id":"01a2190a-ae7d-78fe-b5d7-65f43e08c4e0","description":"Sigmund Freud","correct_answer":false}]},{"id":"01a2190a-ae7d-7d8a-bec7-708974c0cb39","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"How many karats are in pure gold?","difficulty":1,"explanation":"24-karat gold is considered pure; lower ratings indicate that other metals make up part of the alloy.","alternatives":[{"id":"01a2190a-ae7d-798c-86cb-5d74427efe81","description":"24 karat","correct_answer":true},{"id":"01a2190a-ae7d-7e04-8d64-ff5d4ae4def7","description":"22 karat","correct_answer":false},{"id":"01a2190a-ae7d-783e-b10f-2a32b93c3438","description":"30 karat","correct_answer":false},{"id":"01a2190a-ae7d-76c5-83df-675ed126eb45","description":"12 karat","correct_answer":false}]},{"id":"01a2190a-ae7d-7d87-9eee-de2b8f4e67b5","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is radar primarily used for?","difficulty":1,"explanation":"Radar stands for \u201cradio detection and ranging\u201d; the time taken for reflected radio waves to return can reveal how far away something is.","alternatives":[{"id":"01a2190a-ae7d-7682-b02e-17b075bf4ce0","description":"Detecting objects","correct_answer":true},{"id":"01a2190a-ae7d-7ca1-af31-376349463a6d","description":"Amplifying sound","correct_answer":false},{"id":"01a2190a-ae7d-7b58-aeb4-1d44ab6cc48c","description":"Generating electricity","correct_answer":false},{"id":"01a2190a-ae7d-769c-a842-315d0dba330d","description":"Measuring temperature","correct_answer":false}]},{"id":"01a2190a-ae7d-79f0-abd9-2dcaa80d7a1b","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What instrument can we use to observe the stars?","difficulty":1,"explanation":"A telescope collects and focuses light, making distant stars easier to observe. Many large observatory telescopes use mirrors to gather that light.","alternatives":[{"id":"01a2190a-ae7d-7a08-a2c3-2fd32bfd6c26","description":"Telescope","correct_answer":true},{"id":"01a2190a-ae7d-7c79-b888-cf5aed6bf9a3","description":"Periscope","correct_answer":false},{"id":"01a2190a-ae7d-7b34-adce-6dd5633dadc6","description":"Endoscope","correct_answer":false},{"id":"01a2190a-ae7d-7a1e-803b-bf2659ae8555","description":"Microscope","correct_answer":false}]},{"id":"01a2190a-ae7d-734c-b1a8-8158905ce5aa","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What theory describes the start of our universe?","difficulty":1,"explanation":"The Big Bang theory describes the universe expanding from an extremely hot, dense state. The cosmic microwave background is often described as the afterglow of that early universe.","alternatives":[{"id":"01a2190a-ae7d-72bf-b62e-bf6ae80a304d","description":"Big Bang","correct_answer":true},{"id":"01a2190a-ae7d-7e2d-b963-e24ebd836a4b","description":"Supernova","correct_answer":false},{"id":"01a2190a-ae7d-7c60-b570-3f7277ef758e","description":"Standard model","correct_answer":false},{"id":"01a2190a-ae7d-7c92-aff8-1224962ac80d","description":"Special relativity","correct_answer":false}]},{"id":"01a2190a-ae7d-7e9b-b49c-765745ac2d58","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the direct cause of Type I Diabetes?","difficulty":1,"explanation":"In Type I diabetes, the immune system destroys insulin-producing beta cells in the pancreas, so blood glucose can build up.","alternatives":[{"id":"01a2190a-ae7d-72bb-b006-be9e556dbc86","description":"Not enough insulin","correct_answer":true},{"id":"01a2190a-ae7d-7087-8cdb-897adb78aa27","description":"Not enough estrogen","correct_answer":false},{"id":"01a2190a-ae7d-742b-a8a5-8d66bf821883","description":"Not enough calcium","correct_answer":false},{"id":"01a2190a-ae7d-7342-bd21-16f91fa3d128","description":"Not enough magnesium","correct_answer":false}]},{"id":"01a2190a-ae7d-77ed-a371-d16e91bb1c4f","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the transition from liquid to solid phase?","difficulty":1,"explanation":"Freezing is the reverse of melting; boiling and condensation are phase changes involving a gas.","alternatives":[{"id":"01a2190a-ae7d-72ab-82e0-68e367366552","description":"Freezing","correct_answer":true},{"id":"01a2190a-ae7d-7a6b-9084-48979cee221b","description":"Melting","correct_answer":false},{"id":"01a2190a-ae7d-7d1b-a0b7-718beb6dbec0","description":"Boiling","correct_answer":false},{"id":"01a2190a-ae7d-7bff-8900-12d48d319b42","description":"Condensation","correct_answer":false}]},{"id":"01a2190a-ae7d-78c0-8268-d7eafb28b60e","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the name given to the practice of growing plants in liquids rather than soil?","difficulty":1,"explanation":"Hydroponics supplies plant roots with nutrients through a water-based solution. The name combines Greek roots meaning \u201cwater\u201d and \u201clabor.\u201d","alternatives":[{"id":"01a2190a-ae7d-7389-9c2c-02718dfa0dea","description":"Hydroponics","correct_answer":true},{"id":"01a2190a-ae7d-78c0-9402-d338509a97f0","description":"Aquonics","correct_answer":false},{"id":"01a2190a-ae7d-72be-9a49-3a05b2d429c3","description":"Horticulture","correct_answer":false},{"id":"01a2190a-ae7d-75b0-870f-f39f40f0a553","description":"Waterculture","correct_answer":false}]},{"id":"01a2190a-ae7d-7acb-a49f-0099130b08f2","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is Earth\'s primary source of energy?","difficulty":1,"explanation":"The Sun supplies most of the energy reaching Earth, warming the planet and powering processes such as weather and photosynthesis.","alternatives":[{"id":"01a2190a-ae7d-7d4f-8e57-4d625720e9ec","description":"Sun","correct_answer":true},{"id":"01a2190a-ae7d-7e73-a0fc-96b66a5b9db5","description":"Moon","correct_answer":false},{"id":"01a2190a-ae7d-7d33-88b6-f464b288efd6","description":"Venus","correct_answer":false},{"id":"01a2190a-ae7d-7b15-8263-b42459023c6e","description":"Alpha Centauri","correct_answer":false}]},{"id":"01a2190a-ae7d-7332-90d2-53214e1f84e7","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which of these birds is extinct?","difficulty":1,"explanation":"The Dodo lived only on Mauritius; hunting and animals introduced by people contributed to its extinction.","alternatives":[{"id":"01a2190a-ae7d-7831-b78b-cd06dd5099e9","description":"Dodo","correct_answer":true},{"id":"01a2190a-ae7d-77bb-8a5c-7c287a7d8593","description":"Owl","correct_answer":false},{"id":"01a2190a-ae7d-7c7f-87c6-eb394cfe6a2e","description":"Finch","correct_answer":false},{"id":"01a2190a-ae7d-7ce4-9611-92a36b4245b3","description":"Black stork","correct_answer":false}]},{"id":"01a2190a-ae7d-7057-b815-25698c94bd01","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is a baby sheep known as?","difficulty":1,"explanation":"Sheep are ruminants, and their young are commonly called lambs.","alternatives":[{"id":"01a2190a-ae7d-721e-99f1-fd5815979a03","description":"A Lamb","correct_answer":true},{"id":"01a2190a-ae7d-7a90-9851-02ccf9327b49","description":"A Maggot","correct_answer":false},{"id":"01a2190a-ae7d-7e70-9a7c-1e38e2f62f1f","description":"A Caterpillar","correct_answer":false},{"id":"01a2190a-ae7d-746e-9277-7bb3808a319b","description":"A Fry","correct_answer":false}]},{"id":"01a2190a-ae7d-7274-9e31-5dcfa4171359","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which technology was first developed for the U.S. military and is now used for navigation?","difficulty":1,"explanation":"GPS was developed by the U.S. Department of Defense; its satellite signals are now used in phones, cars, and mapping devices.","alternatives":[{"id":"01a2190a-ae7d-7700-940f-219c02386f60","description":"GPS","correct_answer":true},{"id":"01a2190a-ae7d-7148-8fd8-d770cf897108","description":"BPS","correct_answer":false},{"id":"01a2190a-ae7d-7cac-85b3-fa180e3bce9f","description":"LPS","correct_answer":false},{"id":"01a2190a-ae7d-70b2-a214-d2b6a1d3abe8","description":"TPS","correct_answer":false}]},{"id":"01a2190a-ae7d-7ae4-bc2f-cc3e7031c8bb","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What region receives the most heat from the Sun?","difficulty":1,"explanation":"The tropical region gets the most heat because sunlight arrives more directly there; near the poles, it strikes at a lower angle and spreads over a larger area.","alternatives":[{"id":"01a2190a-ae7d-7b7f-88c2-c7608b49eef9","description":"Tropical region","correct_answer":true},{"id":"01a2190a-ae7d-7d02-a8ea-ac93137e38ce","description":"Temperate region","correct_answer":false},{"id":"01a2190a-ae7d-75dd-a2da-db6b24981008","description":"Polar region","correct_answer":false},{"id":"01a2190a-ae7d-7fcb-a035-122bed15b5de","description":"Arctic region","correct_answer":false}]},{"id":"01a2190a-ae7d-7213-ba60-ccde3779b8e8","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"In the human body, what is the name of the structure that runs down the middle of the back?","difficulty":1,"explanation":"The spinal cord is part of the central nervous system, along with the brain.","alternatives":[{"id":"01a2190a-ae7d-7dcd-afcb-a02264de818d","description":"Spinal cord","correct_answer":true},{"id":"01a2190a-ae7d-79c6-b42a-9eab4d17e62b","description":"Vagus nerve","correct_answer":false},{"id":"01a2190a-ae7d-7bbb-80a5-43ad2a20bbeb","description":"Ribcage","correct_answer":false},{"id":"01a2190a-ae7d-7874-8a48-6ad387ca796b","description":"Trachea","correct_answer":false}]},{"id":"01a2190a-ae7d-73a8-a4f5-f7a85774fe7f","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What part of an exhaust converts toxic byproducts of combustion into less toxic ones?","difficulty":1,"explanation":"A catalytic converter uses precious metals to transform carbon monoxide, nitrogen oxides, and unburned hydrocarbons into less harmful gases.","alternatives":[{"id":"01a2190a-ae7d-7289-a06e-0a8481f5242d","description":"Catalytic Converter","correct_answer":true},{"id":"01a2190a-ae7d-7ba9-b4ba-10112289c2f7","description":"Muffler","correct_answer":false},{"id":"01a2190a-ae7d-7c58-beea-96fe9e7bac40","description":"Exhaust Manifold","correct_answer":false},{"id":"01a2190a-ae7d-7177-8dec-91ff77d6e4c3","description":"Turbocharger","correct_answer":false}]},{"id":"01a2190a-ae7d-72ff-acfc-d4a738d56a19","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"A power station with turbines on tall towers on hills or at sea generates electricity from which energy source?","difficulty":1,"explanation":"Wind turbines turn wind\'s kinetic energy into electricity; \'eolic\' power is another word for wind power.","alternatives":[{"id":"01a2190a-ae7d-7ada-98fe-9fc20bfe15da","description":"Wind","correct_answer":true},{"id":"01a2190a-ae7d-7479-a39e-1e3a43fc3e92","description":"Solar","correct_answer":false},{"id":"01a2190a-ae7d-7392-8838-116e25f4687d","de